INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78569, 'spa', 'Copa o vaso de libación — recipiente ancho y poco profundo usado exclusivamente ', 'Copa o vaso de libación — recipiente ancho y poco profundo usado exclusivamente en Apocalipsis para las copas de oro de incienso que contienen las oraciones de los santos (Ap 5:8) y las siete copas de la ira de Dios derramadas en juicio (Ap 15:7; 16:1-17; 17:1; 21:9). El español ''copa'' confirma un único referente tanto en singular como en plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78573, 'spa', 'Amor fraternal', 'Amor y afecto mutuo entre hermanos espirituales: creyentes unidos en comunidad. A diferencia de la amistad genérica, φιλαδελφία conlleva el peso de la obligación familiar y la ternura. En 1 Tesalonicenses 4:9 Pablo dice que los tesalonicenses han sido ''enseñados por Dios'' a practicarlo, y Hebreos 13:1 ordena que ''permanezca''. Las glosas multilingües (español amor fraternal, alemán Bruderliebe) convergen unánimemente en este concepto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78581, 'spa', 'Amar con afecto personal, aprecio cálido o amistad, enfatizando el vínculo emoci', 'Amar con afecto personal, aprecio cálido o amistad, enfatizando el vínculo emocional y el cariño más que el compromiso de principios. En español se emplean tanto ''amar'' como ''querer'' (este último con mayor calidez personal). Los fariseos «aman» los puestos de honor (Mt 23:6; Lc 20:46); Jesús advierte contra amar a la familia más que a él (Mt 10:37). En Juan 21:15-17, el juego entre ἀγαπάω y φιλέω en el diálogo con Pedro ha fascinado a los intérpretes durante siglos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78584, 'spa', 'Besar a alguien, ya sea como saludo habitual, gesto de afecto o señal traidora', 'Besar a alguien, ya sea como saludo habitual, gesto de afecto o señal traidora. Los tres Evangelios sinópticos emplean este sentido para la señal convenida por Judas: «al que yo bese, ese es» (Mt 26:48; Mc 14:44; Lc 22:47). El español distingue claramente este acto físico con ''besar'', mientras otras lenguas conservan su verbo general de amar sin diferenciar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78596, 'spa', 'Beso, ósculo', 'Un beso — el acto físico de presionar los labios sobre otra persona como señal de afecto, saludo o reverencia. El español distingue ''beso'' (beso común) de ''ósculo'' (beso más solemne y litúrgico), reflejando el alcance semántico del término en el NT. En Lc 7:45, los besos de la mujer pecadora expresan amor arrepentido; en Lc 22:48, el beso de Judas es instrumento de traición. Pablo transforma el gesto en práctica litúrgica con el ''ósculo santo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78604, 'spa', 'Ciudad de Filipos', 'La ciudad de Filipos en el este de Macedonia, colonia romana donde Pablo estableció su primera iglesia europea (Hch 16:12). Las cuatro apariciones neotestamentarias la señalan como punto de referencia geográfico en la narrativa misionera paulina: lugar de la conversión de Lidia y la salvación del carcelero, escala en el viaje de regreso (Hch 20:6), y comunidad destinataria de la carta a los Filipenses (Fil 1:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78605, 'spa', 'Felipe (nombre propio)', 'Felipe (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78613, 'spa', 'Hospitalario con extraños', 'Primera Timoteo 3:2 exige que el obispo sea «hospitalario» (φιλόξενον), acogedor con extraños y huéspedes. Tito 1:8 requiere igualmente que el anciano sea «hospitalario» (φιλόξενον), junto con otras virtudes. Primera Pedro 4:9 manda a todos los creyentes practicar la hospitalidad mutuamente sin quejarse, como expresión concreta del amor fraternal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78615, 'spa', 'Amigo o compañero querido, alguien unido por afecto mutuo y lealtad', 'Amigo o compañero querido, alguien unido por afecto mutuo y lealtad. Jesús redefine φίλος teológicamente: «Vosotros sois mis amigos si hacéis lo que yo os mando» (Jn 15:14-15), elevando a los discípulos de siervos a amigos. El término también aparece en contraste negativo — advierten a Pilato «no eres amigo del César» (Jn 19:12) — y en contextos de hospitalidad como Lázaro (Jn 11:11) y la parábola del amigo a medianoche (Lc 11:5-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78624, 'spa', 'Ambición santa', 'Romanos 15:20 explica la estrategia misionera de Pablo: se propuso como «ambición» (φιλοτιμούμενον) predicar donde Cristo aún no era conocido, abriendo camino nuevo. Segunda Corintios 5:9 declara su meta central: «nos esforzamos» (φιλοτιμούμεθα) por agradar a Cristo, ya sea en el cuerpo o fuera de él. Primera Tesalonicenses 4:11 exhorta a los creyentes a «tener por ambición» vivir tranquilamente y trabajar con sus propias manos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78626, 'spa', 'Silenciar, hacer callar', 'Silenciar, hacer callar, dejar sin habla: la extensión figurada de amordazar aplicada al habla y fuerzas sobrenaturales. Jesús ordena al espíritu inmundo «¡Cállate!» (Mr 1:25, φιμώθητι), y la misma palabra reprende al viento y al mar (Mr 4:39). En Mt 22:34 los saduceos quedan «amordazados» por los argumentos de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78627, 'spa', 'Amordazar, poner bozal', 'Amordazar a un animal, impidiéndole comer mientras trabaja: el sentido original y literal. Ambas ocurrencias (1 Co 9:9; 1 Ti 5:18) citan Dt 25:4: «No pondrás bozal al buey que trilla.» Pablo usa esta ley agrícola como argumento a fortiori para sustentar a los obreros del evangelio. El español «pondrás bozal» conserva la imagen concreta del acto de amordazar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78636, 'spa', 'Llama, fuego ardiente', 'Llama o fuego ardiente: la porción visible y resplandeciente de una combustión. En el NT aparece en contextos teofánicos y escatológicos: la zarza ardiente (Hch 7:30), ángeles como llamas de fuego (Heb 1:7), Cristo revelado en llama de fuego (2 Ts 1:8), sus ojos como llama (Ap 1:14) y el fuego atormentador del Hades (Lc 16:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78641, 'spa', 'Temible ante Dios', 'Hebreos 10:27 advierte a los apóstatas de una expectativa «temible» de juicio y fuego consumidor. Hebreos 10:31 declara que es «temible» caer en manos del Dios vivo. Hebreos 12:21 describe la reacción de Moisés ante el Sinaí como algo tan «terrible» que temblaba de miedo. Los tres usos subrayan la respuesta apropiada ante la santidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78642, 'spa', 'Tener miedo, temer', 'Sentir miedo, experimentar temor o alarma ante el peligro, la amenaza o lo sobrenatural. Este sentido dominante (83 apariciones) abarca el terror humano ante tormentas (Mt 14:26), el miedo a las autoridades (Mt 10:28), el pavor ante malas noticias (Mt 1:20, «no temas») y la alarma ante manifestaciones divinas. El español «temieron/temáis» traduce consistentemente este temor visceral e involuntario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78647, 'spa', 'Reverenciar, temer a Dios', 'Reverenciar, adorar o sentir asombro ante Dios; una disposición estable más que un sobresalto momentáneo. Lucas 1:50 («Su misericordia es para los que le temen») y Hechos 10:2, 22, 35 (Cornelio como «temeroso de Dios») emplean este sentido prácticamente como marca de identidad religiosa. No se trata de terror sino de un respeto profundo que moldea toda la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78657, 'spa', 'Respetar, reverenciar', 'Una única aparición en Ef 5:33, donde se exhorta a la esposa a «temer» (φοβῆται) a su esposo; no un terror servil, sino un respeto que refleja la reverencia de la iglesia hacia Cristo. Es significativo que el español escoge «respete» en lugar de un verbo de temor, revelando cómo la traducción interpreta esta extensión semántica hacia la deferencia conyugal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78669, 'spa', 'temor, espanto, reverencia', 'temor, espanto, reverencia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78675, 'spa', 'Región costera fenicia', 'Hechos 11:19 relata cómo los creyentes dispersos por la persecución tras Esteban llegaron hasta Fenicia, Chipre y Antioquía, predicando inicialmente solo a judíos. Hechos 15:3 describe a Pablo y Bernabé atravesando Fenicia camino al concilio de Jerusalén, informando las conversiones gentiles. Hechos 21:2 menciona a Pablo embarcándose hacia Fenicia, mostrando su papel como corredor de viaje misionero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78679, 'spa', 'Asesino, homicida', 'Asesino u homicida: quien mata ilícitamente a otro ser humano de forma deliberada. Esteban acusa al Sanedrín de ser ''homicidas'' del Justo (Hch 7:52), en Mateo 22:7 un rey destruye a los asesinos de sus mensajeros, los malteses suponen que Pablo es homicida (Hch 28:4), y en 1 Pedro 4:15 se advierte contra sufrir como tal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78683, 'spa', 'Cometer asesinato — el verbo del Sexto Mandamiento que prohíbe el homicidio ilíc', 'Cometer asesinato — el verbo del Sexto Mandamiento que prohíbe el homicidio ilícito. Citado en las referencias al Decálogo (Mateo 5:21; 19:18; Romanos 13:9; Santiago 2:11), profundizado por Jesús para incluir la ira (Mateo 5:21-22) y empleado como acusación profética por Santiago (Santiago 4:2; 5:6). El español ''matar'' abarca todas las ocurrencias como un sentido indiviso de homicidio ilícito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78693, 'spa', 'Homicidio, asesinato', 'El acto de homicidio o matanza violenta: la privación deliberada e ilícita de la vida humana. Jesús identifica φόνος como impureza nacida del corazón (Mt 15:19; Mr 7:21), junto al adulterio y el robo. Lucas lo aplica al crimen de Barrabás (Lc 23:19, 25; Mr 15:7). Pablo lo incluye en catálogos de vicios (Ro 1:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78698, 'spa', 'Llevar, portar habitualmente', 'Vestir o portar habitualmente sobre la propia persona, ya sea ropa (Mateo 11:8, Juan 19:5), un arma o símbolo de autoridad (Romanos 13:4, donde el gobernante ''porta'' la espada), o una imagen (1 Corintios 15:49, llevar la semejanza de Adán o de Cristo). El aspecto frecuentativo lo distingue del simple φέρω, implicando un porte continuo y característico. La evidencia multilingüe (español llevar, alemán tragen) lo confirma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78705, 'spa', 'Tributo imperial', 'Pago monetario obligatorio debido a una autoridad política, específicamente el tributo exigido por el Imperio Romano a los pueblos sometidos. Jesús aborda la cuestión de su licitud en Lc 20:22, y Pablo ordena su pago como deber hacia los poderes gobernantes que Dios ha establecido (Ro 13:6-7). Las cinco apariciones se refieren a la obligación cívica del pago de impuestos bajo el dominio romano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78707, 'spa', 'Carga personal', 'Una carga o peso que lleva una persona, ya sea físico o figurado: responsabilidad, obligación o dificultad. Jesús contrasta su carga ligera con los pesados fardos que imponen los fariseos (Mateo 11:30; 23:4; Lucas 11:46), y Pablo enseña que cada persona debe llevar su propia carga (Gálatas 6:5). Las traducciones en español carga, hindi bojh y alemán Last convergen en este matiz personal y gravoso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78710, 'spa', 'Carga marítima', 'Carga o mercancía transportada por un barco, distinta de las cargas personales. En Hechos 27:10 Pablo advierte que el viaje traerá desastre ''a la carga y al navío''. Las traducciones cambian notablemente: el inglés usa cargo en vez de burden, el hindi pasa a maalke (bienes/propiedad), y el contexto comercial marítimo distingue este sentido claramente del peso personal de las demás ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78714, 'spa', 'Cerca o muro divisorio', 'Una cerca, seto o muro divisorio que funciona como barrera física o metafórica. En las parábolas de la viña (Mt 21:33; Mr 12:1) designa un seto protector que hace eco de Isaías 5:2. En Lucas 14:23 marca los vallados junto a los caminos donde se congregan los marginados. Efesios 2:14 extiende la imagen metafóricamente al muro divisorio de hostilidad entre judío y gentil, que Cristo ha abolido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78716, 'spa', 'Silenciar o bloquear', 'Romanos 3:19 explica que la ley hace que toda boca «sea cerrada» y el mundo entero quede bajo el juicio de Dios, un silenciamiento universal sin defensa posible. 2 Corintios 11:10 usa la forma pasiva futura: Pablo afirma que su motivo de orgullo «no será detenido» en Acaya. Hebreos 11:33 celebra a quienes por fe «cerraron bocas de leones», evocando la liberación de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78717, 'spa', 'Pozo, foso', 'Pozo, foso o cavidad profunda que abarca tanto el sentido práctico de un pozo excavado para agua (Jn 4:11-12, donde la samaritana señala que es hondo) como el sentido apocalíptico de un abismo sin fondo (Ap 9:1-2, el pozo del abismo). La LXX también lo emplea para fosas de destrucción (cf. Sal 55:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78723, 'spa', 'El sentido cognitivo activo', 'El sentido cognitivo activo: pensar, considerar o reflexionar sobre un asunto, formando opiniones o deliberando. Cubre la mayoría de las apariciones, incluida la reprensión de Jesús en Mt 16:23 («no piensas en las cosas de Dios») y la exhortación de Pablo en Ro 12:3 sobre una evaluación sobria de uno mismo. El español ''pensar'' y el francés ''penser'' expresan de manera consistente esta actividad intelectual directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78726, 'spa', 'Un sentido disposicional sostenido', 'Un sentido disposicional sostenido: poner la mente en algo, considerar o preocuparse habitualmente por algo. Se distingue de la cognición momentánea al implicar una orientación continua de la atención. Romanos 8:5 es el caso paradigmático: los que viven según la carne «piensan» en las cosas de la carne. El alemán ''gesinnt sein'' (tener cierta disposición) capta bien este matiz de actitud mental arraigada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78739, 'spa', 'Mentalidad interior', 'La disposición arraigada o mentalidad profunda de una persona, especialmente según esté determinada por la carne o el Espíritu. En Romanos 8:6 Pablo afirma que la mentalidad de la carne es muerte, mientras que la del Espíritu es vida y paz. En 8:7 la mentalidad carnal es hostil a Dios. En 8:27 Dios escudriña la mentalidad del Espíritu mismo en los corazones de los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78741, 'spa', 'Sabio, prudente — que posee sabiduría práctica y buen juicio, la capacidad de di', 'Sabio, prudente — que posee sabiduría práctica y buen juicio, la capacidad de discernir el curso correcto de acción y llevarlo a cabo. Es el sentido dominante en el NT, presente en las parábolas de preparación de Jesús: el constructor prudente (Mateo 7:24), las vírgenes prudentes (Mateo 25:2, 4, 8, 9) y el mayordomo fiel (Mateo 24:45; Lucas 12:42). El español lo traduce consistentemente como ''prudente(s)''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78745, 'spa', 'Sagaz, astuto (comparativo) — con connotación de astucia ingeniosa que se encuen', 'Sagaz, astuto (comparativo) — con connotación de astucia ingeniosa que se encuentra en tensión moral con la sabiduría directa. En Lucas 16:8, Jesús observa que ''los hijos de este siglo son más sagaces con los de su generación que los hijos de la luz''. Aquí la forma comparativa no señala virtud sino cálculo perspicaz. El español pasa de ''prudentes'' a ''más sagaces'', reflejando el cambio semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78748, 'spa', 'Guardar, custodiar', 'Guardar, guarnecionar o mantener bajo vigilancia protectora, originalmente un término militar para apostar centinelas. En 2 Corintios 11:32 describe a soldados custodiando Damasco para arrestar a Pablo. Gálatas 3:23 lo emplea metafóricamente para la ley manteniendo a Israel en custodia antes de que se revelara la fe. En Filipenses 4:7 la imagen se vuelve cálida: la paz de Dios guarnicionará los corazones de los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78751, 'spa', 'Región de Frigia', 'Hechos 2:10 incluye a los frigios entre los judíos devotos presentes en Pentecostés, oyendo el evangelio en sus propias lenguas. Hechos 16:6 describe a Pablo y sus compañeros atravesando la región frigia y gálata tras ser impedidos de entrar en Asia por el Espíritu. Hechos 18:23 narra a Pablo recorriendo sucesivamente la región gálata y frigia, fortaleciendo a todos los discípulos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78754, 'spa', 'cárcel, lugar de reclusión', 'cárcel, lugar de reclusión');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78756, 'spa', 'vigilia, período nocturno', 'vigilia, período nocturno');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78759, 'spa', 'guardia, puesto de guardia', 'guardia, puesto de guardia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78763, 'spa', 'Guardias de prisión', 'Hechos 5:23 describe a los oficiales encontrando la cárcel cerrada con seguridad y los guardias apostados en las puertas, pero al abrirlas no hallaron a nadie dentro: la liberación angélica dejó a los guardias en su puesto, resaltando lo milagroso. Hechos 12:6 muestra a Pedro durmiendo entre dos soldados mientras los centinelas custodiaban la puerta, seguridad máxima que no fue barrera para el ángel de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78764, 'spa', 'guardar, observar mandamientos', 'guardar, observar mandamientos');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78765, 'spa', 'custodiar, vigilar', 'custodiar, vigilar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78766, 'spa', 'preservar, proteger del mal', 'preservar, proteger del mal');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78770, 'spa', 'guardarse de, precaverse', 'guardarse de, precaverse');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78790, 'spa', 'tribu, clan', 'tribu, clan');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78794, 'spa', 'Hojas, follaje', 'Las hojas o follaje de un árbol, empleadas en los Evangelios sinópticos para describir la manifestación estacional de la higuera. En Marcos 11:13 la presencia de hojas sin fruto se convierte en símbolo de apariencia engañosa, mientras que en la parábola de la higuera (Mateo 24:32, Marcos 13:28) las hojas nuevas anuncian la cercanía de la estación esperada. Las glosas interlingüísticas (español hojas, francés feuilles, alemán Blätter) convergen uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78796, 'spa', 'Masa amasada', 'Una porción o masa de harina amasada, usada en el NT exclusivamente en contextos figurados para representar un cuerpo colectivo: ya sea una comunidad expuesta a influencia moral (1 Co 5:6-7, Gá 5:9, ''un poco de levadura leuda toda la masa''), un pueblo cuyas primicias consagran el todo (Ro 11:16), o barro en manos del alfarero que representa a la humanidad bajo la soberanía divina (Ro 9:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78797, 'spa', 'Conforme a la naturaleza', 'La evidencia multilingüe (inglés ''natural'', español ''natural/naturales'', francés ''naturel'', alemán ''natürlich'') muestra una traducción uniforme que refleja el sentido filosófico de ''perteneciente a la naturaleza''. En Romanos 1, Pablo contrasta las relaciones ''naturales'' con las ''contra naturaleza'', empleando una distinción bien establecida en la filosofía moral grecorromana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78799, 'spa', 'Estar hinchado, envanecerse', 'Estar inflado de vanidad, hinchado de arrogancia (voz pasiva/media). Abarca el uso paulino donde los corintios son sujetos de inflación espiritual: envanecidos a favor de un líder contra otro (1 Co 4:6), arrogantes como si Pablo no viniera (1 Co 4:18-19), hinchados ante la inmoralidad (1 Co 5:2), y el amor que ''no se envanece'' (1 Co 13:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78801, 'spa', 'Inflar, envanecer', 'Causar que alguien se hinche de orgullo, inflar de vanidad (voz activa). En 1 Corintios 8:1, ''el conocimiento envanece'': la gnosis es el agente activo que infla el ego, puesto en contraste deliberado con el amor que ''edifica'' (οἰκοδομεῖ). La voz activa deposita la responsabilidad en aquello que causa la arrogancia, no en quien la experimenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78806, 'spa', 'Naturaleza — el carácter inherente, constitución o cualidad esencial de una pers', 'Naturaleza — el carácter inherente, constitución o cualidad esencial de una persona o cosa. Este sentido trata φύσις como sustantivo que denota la naturaleza misma — lo que algo es fundamentalmente. Pablo lo usa para discutir lo que concuerda con o viola el orden natural (Romanos 1:26, ''contra naturaleza''), y en su metáfora del olivo donde las ramas pertenecen al árbol cultivado ''por naturaleza'' frente a ser injertadas (Romanos 11:21, 24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78807, 'spa', 'Por naturaleza — uso adverbial que significa ''por naturaleza'' o ''naturalmente'', ', 'Por naturaleza — uso adverbial que significa ''por naturaleza'' o ''naturalmente'', enfatizando lo que es innato o inherente desde el nacimiento en vez de adquirido. En Romanos 2:14, los gentiles que no tienen la Torá pero ''por naturaleza'' hacen lo que ella requiere demuestran un sentido moral innato. Gálatas 2:15 distingue a quienes son ''por naturaleza'' judíos de los pecadores gentiles. Gálatas 4:8 habla de servir a seres que ''por naturaleza'' no son dioses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78811, 'spa', 'Plantar literalmente — colocar un árbol, vid o cultivo en la tierra para su cult', 'Plantar literalmente — colocar un árbol, vid o cultivo en la tierra para su cultivo. Las parábolas de la viña lo usan para el establecimiento agrícola (Mt 21:33; Mr 12:1; Lc 13:6), y aparece en el dicho sobre Lot acerca de la vida cotidiana antes del juicio (Lc 17:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78818, 'spa', 'Brotar o germinar', 'Las traducciones multilingües destacan la acción de brotar o crecer: inglés ''springing'', español ''brotando'', francés ''pousser'', alemán ''wachsen''. Lucas 8:6 describe la semilla que brotó pero se secó por falta de humedad; el versículo 8 relata la que creció al ciento por uno. Hebreos 12:15 usa la imagen metafóricamente para la amargura que puede surgir y causar daño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78820, 'spa', 'Llamar o convocar a alguien por su nombre para que venga', 'Llamar o convocar a alguien por su nombre para que venga. Jesús llama a Lázaro (Juan 12:17), el ciego es convocado (Marcos 10:49) y los obreros son llamados a recibir su salario (Mateo 20:32). El español ''llamar'' captura de manera consistente este sentido interpersonal de convocatoria en las 24 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78821, 'spa', 'El canto característico del gallo, usado exclusivamente en los relatos de la Pas', 'El canto característico del gallo, usado exclusivamente en los relatos de la Pasión referentes a la negación de Pedro. Jesús predice que el gallo cantará antes de que Pedro lo niegue tres veces (Mateo 26:34; Marcos 14:30). El español emplea ''cantar'', un modismo natural para la vocalización de las aves.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78825, 'spa', 'Gritar, clamar o exclamar con intensidad vocal, sin necesariamente convocar a al', 'Gritar, clamar o exclamar con intensidad vocal, sin necesariamente convocar a alguien en particular. Un espíritu inmundo clama (Marcos 1:26), Jesús grita con gran voz desde la cruz (Lucas 23:46) y clama a la multitud ''¡El que tiene oídos, oiga!'' (Lucas 8:8). El español ''clamar'' capta este registro elevado, distinto del llamar ordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78838, 'spa', 'voz, sonido vocal', 'Voz o sonido vocal producido por un ser vivo — humano, angélico o divino. Este sentido abrumadoramente dominante (137 de 139 ocurrencias) abarca todo el registro, desde el habla susurrada hasta las declaraciones celestiales atronadoras. Las lenguas de traducción convergen: español ''voz'', francés ''voix'', alemán ''Stimme''. Pasajes clave incluyen la voz celestial en el bautismo (Mt 3:17) y la voz del Bautista en el desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78842, 'spa', 'sonido, ruido (no vocal)', 'Sonido audible no vocal o ruido — de instrumentos, fuerzas naturales o eventos cósmicos. Atestiguado solo dos veces en el NT: la discusión de Pablo sobre diversos ''tipos de sonidos'' en el mundo (1 Co 14:10) y el grito del águila que introduce los ayes en Ap 8:13. El español cambia de ''voz'' a ''sonidos'', señalando la extensión semántica de la emisión vocal al fenómeno acústico en general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78845, 'spa', 'Luz, iluminación', 'La luz en toda su amplitud: luz natural del día (Mt 17:2), resplandor divino (2 Co 4:6), iluminación espiritual (Jn 1:5; 8:12) y transparencia moral (Mt 5:16). Este sentido domina con 71 de 72 apariciones. Las traducciones son notablemente uniformes — español «luz», francés lumière, alemán Licht — reflejando cómo abarcan con naturalidad el mismo espectro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78847, 'spa', 'Resplandor del fuego', 'La claridad emitida por un fuego, atestiguada únicamente en Marcos 14:54, donde Pedro se calienta junto al fuego en el patio del sumo sacerdote. La evidencia multilingüe separa este uso de la luz genérica: el hindi emplea «aag» (fuego) en vez del habitual «jyoti» (luz), y varias lenguas recurren a vocabulario específico del fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78851, 'spa', 'Luminoso, resplandeciente', 'Brillante, radiante o lleno de luz, aplicado tanto a la luminosidad física como a la iluminación espiritual-moral. Describe la nube resplandeciente de la gloria divina en la Transfiguración (Mt 17:5) y el estado de la persona cuyo ‘ojo’ interior está sano y sin oscuridad, permitiendo que todo el cuerpo se inunde de luz (Mt 6:22; Lc 11:34, 36). Las cinco ocurrencias vinculan el resplandor exterior con la integridad interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78852, 'spa', 'Iluminar, alumbrar físicamente', 'Iluminar, alumbrar físicamente. Iluminar física o escatológicamente, haciendo brillar luz sobre un lugar o personas. En Apocalipsis 18:1, la gloria de un ángel ilumina la tierra; en 21:23 y 22:5, la gloria de Dios y del Cordero reemplazan al sol y a la lámpara como fuente de luz de la ciudad. El español distingue tiempos: ''fue iluminada'' frente a ''alumbrará'', marcando si la iluminación es visionaria o profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78853, 'spa', 'Iluminar espiritualmente, dar entendimiento', 'Iluminar espiritualmente, dar entendimiento. Alumbrar a una persona espiritualmente, concediéndole discernimiento, comprensión o conversión. Juan 1:9 lo usa de la luz verdadera que alumbra a toda persona; Hebreos 6:4 y 10:32 hablan de los ''una vez iluminados'', una experiencia tan formativa que el español ''iluminados'' y el alemán ''erleuchtet'' se convirtieron en términos casi técnicos para la iluminación bautismal. Lucas 11:36 lo aplica a la luz interior que llena todo el cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78859, 'spa', 'Sacar a la luz, revelar', 'Sacar a la luz, revelar. Traer algo oculto a lo público, revelar o dar a conocer. En Efesios 3:9 la misión de Pablo es ''sacar a la luz'' el misterio del plan de Dios escondido por siglos, donde el español ''iluminar'' extiende la metáfora de la luz a la divulgación. En 2 Timoteo 1:10, Cristo ha ''sacado a la luz'' la vida y la inmortalidad por medio del evangelio, la revelación definitiva que transforma posibilidades ocultas en realidad manifiesta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78862, 'spa', 'Regocijarse, alegrarse', 'Experimentar o expresar gozo y deleite; el núcleo emocional de la palabra en 63 apariciones. Los magos se regocijaron con gran gozo (Mt 2:10), Jesús dijo a los perseguidos «regocijaos y alegraos» (Mt 5:12), y el pastor se alegra más por la oveja hallada (Lc 15:5). El español alterna «alegraos», «gozaos» y «regocijaos».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78864, 'spa', 'Saludar, decir «¡Salve!»', 'Un saludo formulario — «¡Salve!» o «¡Saludos!» — derivado del imperativo «alégrate» pero que funciona como fórmula convencional de salutación. Aparece en 11 ocasiones. El ángel Gabriel dice «¡Alégrate, favorecida!» a María (Lc 1:28), la instancia más rica teológicamente, mientras que los soldados lo convierten en escarnio: «¡Salve, Rey de los judíos!» (Mt 27:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78890, 'spa', 'Granizo de juicio', 'Granizo o piedras de granizo que aparecen en el NT exclusivamente en contextos de juicio apocalíptico dentro del Apocalipsis. En 8:7 granizo mezclado con fuego y sangre es arrojado a la tierra al sonar la primera trompeta. En 11:19 un gran granizo acompaña la apertura del templo celestial. Apocalipsis 16:21 describe piedras de peso extraordinario cayendo sobre la humanidad rebelde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78891, 'spa', 'Bajar, descender', 'Bajar o descender mediante cuerda o cabo, denotando siempre un descenso controlado. Aparece con fuerte concreción física: un paralítico bajado por el techo (Mr 2:4), redes echadas a aguas profundas (Lc 5:4-5), Pablo descendido en una canasta por la muralla (Hch 9:25) y aparejos náuticos arriados en una tempestad (Hch 27:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78906, 'spa', 'Cobre o bronce', 'Cobre o bronce como material y, por metonimia, las monedas u objetos fabricados con él. Abarca el dinero de cobre que Jesús prohíbe como provisión misionera (Mt 10:9; Mc 6:8), las monedas de bronce depositadas en el arca del templo (Mc 12:41), el gong de bronce resonante como metáfora de la elocuencia vacía sin amor (1 Co 13:1) y el bronce enumerado entre los bienes comerciales en la caída de Babilonia (Ap 18:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78910, 'spa', 'Gozo, alegría profunda', 'Gozo o deleite profundo, arraigado en la acción redentora de Dios, el evangelio y la obra del Espíritu. Describe la respuesta al nacimiento de Cristo (Mt 2:10; Lc 2:10), la acogida de la palabra (Mt 13:20, 44), fruto del Espíritu (Ga 5:22) y recompensa del siervo fiel (Mt 25:21, 23). Jesús habla de «mi gozo» cumplido en los suyos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78911, 'spa', 'Marca de la Bestia', 'La marca estampada de la Bestia en Apocalipsis: señal visible de lealtad impuesta sobre las personas, que funciona como identificación y control económico (Ap 13:16-17: nadie puede comprar ni vender sin ella). Contrasta directamente con el sello de Dios en la frente de los redimidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78912, 'spa', 'Grabado, obra artesanal', 'Un grabado u obra tallada producida por el arte humano. En Hch 17:29, Pablo argumenta ante los atenienses que la naturaleza divina (τὸ θεῖον) no debe concebirse como algo semejante al oro, la plata o la piedra, un χάραγμα del ingenio humano. El español «grabado» capta este sentido artesanal, distinto de la marca escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78915, 'spa', 'Perdonar, indultar o cancelar graciosamente una deuda o transgresión', 'Perdonar, indultar o cancelar graciosamente una deuda o transgresión. Es el sentido más frecuente (12 apariciones), anclado en la parábola de Jesús donde un acreedor «perdonó» a ambos deudores (Lc 7:42). Pablo extiende el concepto: «perdonándoos unos a otros, como Dios os perdonó en Cristo» (Ef 4:32; Col 2:13). La raíz en χάρις (gracia) subraya que se trata de una cancelación inmerecida de lo que se debe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78917, 'spa', 'Entregar, poner en manos de otro o ceder la custodia de una persona', 'Entregar, poner en manos de otro o ceder la custodia de una persona. Este sentido jurídico aparece solo dos veces, ambas en Hechos 25. Festo explica a Agripa que no es costumbre romana «entregar» a nadie sin juicio previo (Hch 25:16), y Pablo afirma que nadie puede «entregarlo» a sus acusadores (Hch 25:11). El contexto legal formal distingue claramente esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78920, 'spa', 'Dar graciosamente, conceder libremente como don del favor divino', 'Dar graciosamente, conceder libremente como don del favor divino. Este sentido (9 apariciones) pone en primer plano la generosidad inherente a la raíz χάρις. Dios «concedió» a Pablo las vidas de todos a bordo (Hch 27:24), y el Espíritu revela lo que Dios ha «dado gratuitamente» (1 Co 2:12). En Fil 1:29, el sufrimiento mismo es «concedido» como don junto con la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78932, 'spa', 'Por causa de', 'Preposición impropia (acusativo fosilizado de χάρις) que significa «a causa de» o «por causa de», expresando causa o propósito. Rige genitivo. Jesús declara que los pecados de la mujer son perdonados porque amó mucho, indicando χάριν la causa (Lc 7:47). Pablo lo usa para propósito: la ley fue añadida «a causa de las transgresiones» (Gá 3:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78937, 'spa', 'gracia, favor divino', 'El gran sentido teológico: el favor inmerecido y la benevolencia de Dios hacia la humanidad, especialmente manifestados a través de la obra salvadora de Cristo. Es el uso dominante en el NT (141 de 157 ocurrencias). El saludo paulino distintivo ''gracia y paz'' (χάρις καὶ εἰρήνη) enmarca cada carta que Pablo escribe. El español ''gracia'' y el alemán ''Gnade'' rastrean este sentido con fidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78939, 'spa', 'gracias, gratitud', 'Expresión de agradecimiento o gratitud, frecuentemente dirigida a Dios. Se distingue del sentido 1 por el contexto: ''¿qué mérito (χάρις) tenéis?'' (Lc 6:32-34) emplea la palabra en un marco de reciprocidad — si solo amáis a quienes os aman, ¿dónde está la gracia? Ro 6:17 (''gracias a Dios'') y 1 Co 15:57 muestran el uso doxológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78940, 'spa', 'favor, acto de bondad', 'Acto concreto de buena voluntad o disposición favorable de una persona hacia otra, especialmente en contextos políticos o judiciales. Las tres ocurrencias aparecen en Hechos: Félix deja a Pablo preso ''queriendo hacer un favor (χάριτα) a los judíos'' (Hch 24:27); los líderes judíos piden a Festo el favor (χάριν) de trasladar a Pablo a Jerusalén (Hch 25:3, 9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78945, 'spa', 'don, dádiva', 'Regalo material o contribución caritativa entregada como acto de generosidad. Aparece una vez en 1 Corintios 16:3, donde Pablo instruye a la iglesia para que prepare su χάρις (don/beneficencia) para Jerusalén. El español ''gracia'' mantiene la misma forma, pero el inglés ''gift'' y otras lenguas distinguen claramente este significado concreto y monetario del sentido teológico abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78950, 'spa', 'Don, don de gracia, dotación espiritual', 'Don, don de gracia, dotación espiritual: don otorgado libremente por la gracia divina, que abarca dotaciones espirituales para el ministerio dentro de la comunidad creyente (profecía, sanidad, lenguas, enseñanza — 1 Co 12:4-11; Ro 12:6), el don de la salvación y la vida eterna (Ro 5:15-16; 6:23), y el llamamiento irrevocable de Dios a Israel (Ro 11:29). La palabra enfatiza que estas capacidades se originan en la generosidad de Dios y no en el mérito humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78956, 'spa', 'Labios', 'Los labios físicos, particularmente como instrumento del habla, la oración y la alabanza. En Hebreos 13:15, el ''fruto de labios'' (καρπὸν χειλέων) designa la adoración verbal; en 1 Corintios 14:21, Pablo cita Isaías 28:11 acerca de Dios hablando por medio de labios extranjeros, una imagen llamativa de lenguas ajenas como instrumentos divinos. El español ''labios'' y el francés ''lèvres'' capturan este sentido con fidelidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78957, 'spa', 'Orilla', 'La orilla o borde de un cuerpo de agua, extendiendo la metáfora anatómica del ''labio'' a un límite geográfico. En Hebreos 11:12, en eco de Génesis 22:17 (LXX), describe la arena ''a lo largo del labio del mar''. El español ''orilla'' captura con precisión este sentido espacial de frontera entre la tierra y el agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78962, 'spa', 'Invierno (estación)', 'La estación invernal, la época fría del año. Jesús insta a orar para que la huida no sea en invierno (Matt 24:20; Mark 13:18), la Fiesta de la Dedicación se celebra en invierno (John 10:22) y Pablo pide a Timoteo llegar antes del invierno (2 Tim 4:21). Las traducciones convergen: español «invierno», francés «hiver».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78963, 'spa', 'Tempestad, tormenta', 'Tormenta o tempestad, clima violento y peligroso, especialmente en el mar. Un cielo rojo matutino anuncia tormenta (Matt 16:3), y una feroz tempestad azota el barco de Pablo hasta que «se perdió toda esperanza de salvarse» (Acts 27:20). Las traducciones divergen del sentido invernal: el español cambia a «tempestad» y el contexto pasa al peligro marítimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78966, 'spa', 'mano / manos', 'La mano o manos humanas como parte física del cuerpo, extendiéndose por metonimia a la agencia, el poder, la custodia y la acción divina. Cubre el uso literal (el toque sanador en Mc 6:5; las manos traspasadas en Lc 24:40), la agencia instrumental (''por mano de'', Hch 7:25) y el modismo teológico (''la diestra de Dios'', Hch 2:33). El español ''manos'' exhibe la misma amplitud polisémica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78973, 'spa', 'Hecho a mano', 'Construido o fabricado por manos humanas, en contraste con lo divino o espiritual. El discurso de Esteban (Acts 7:48) y el de Pablo en el Areópago (Acts 17:24) insisten en que Dios no habita en estructuras χειροποίητος. En Eph 2:11 la circuncisión se califica como «hecha en la carne por manos», relativizándola ante una realidad espiritual mayor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78978, 'spa', 'Peor en condición o severidad — que describe un estado físico, espiritual o situ', 'Peor en condición o severidad — que describe un estado físico, espiritual o situacional deteriorado. La mujer con hemorragia ''empeoró'' bajo los médicos (Mr 5:26), un desgarro en la ropa se agrava con un remiendo inadecuado (Mt 9:16; Mr 2:21), y la re-posesión deja al endemoniado ''peor que antes'' (Mt 12:45). Los apóstatas igualmente enfrentan un estado final ''peor'' (2 P 2:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78984, 'spa', 'Mujer cuyo esposo ha fallecido, que ocupa una posición socialmente vulnerable qu', 'Mujer cuyo esposo ha fallecido, que ocupa una posición socialmente vulnerable que las Escrituras señalan repetidamente como merecedora de protección y justicia. Jesús condena a quienes explotan a las viudas (Marcos 12:40; Lucas 20:47) y exalta la ofrenda sacrificial de la viuda (Marcos 12:42-43; Lucas 21:2-3). Lucas destaca a las viudas como modelos de fe: Ana la profetisa (Lucas 2:37), la viuda de Naín cuyo hijo Jesús resucita (Lucas 7:12) y la viuda persistente que ejemplifica la oración incesante (Lucas 18:3-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78989, 'spa', 'Referencia temporal: ayer', 'El término se traduce uniformemente en todos los idiomas: inglés ''yesterday'', español ''ayer'', francés ''hier'', alemán ''gestern'', todos derivados de raíces indoeuropeas que designan el día anterior. Juan 4:52 lo usa como referencia temporal precisa del momento de la sanidad. Hechos 7:28 alude al asesinato del egipcio por Moisés el día previo. Hebreos 13:8 lo emplea teológicamente para afirmar la naturaleza inmutable de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78990, 'spa', 'El número cardinal mil o un grupo contado en millares, utilizado en recuentos na', 'El número cardinal mil o un grupo contado en millares, utilizado en recuentos narrativos (Hechos 4:4; 1 Corintios 10:8) y en las cifras simbólicas de Apocalipsis: los 144.000 sellados (Apocalipsis 7:4-8), el reinado de mil años (Apocalipsis 20:2-6) y las miríadas celestiales (Apocalipsis 5:11). El español ''mil'' y el francés ''mille'' confirman un tratamiento semántico uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (78994, 'spa', 'Tribuno militar romano que comandaba aproximadamente mil soldados, el oficial de', 'Tribuno militar romano que comandaba aproximadamente mil soldados, el oficial de mayor rango de una cohorte estacionada en una ciudad de guarnición. En Hechos 21:31-33 el quiliarca de la cohorte de Jerusalén interviene para rescatar a Pablo de una multitud violenta; en Juan 18:12 un quiliarca participa en el arresto de Jesús. Las traducciones al español usan ''tribuno'' o ''comandante'', resaltando la autoridad de mando inherente al rango.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79000, 'spa', 'El número cardinal mil, usado para cantidades literales y duraciones proféticas ', 'El número cardinal mil, usado para cantidades literales y duraciones proféticas simbólicas. Pedro relativiza el tiempo terrenal: ''mil años es como un día'' (2 P 3:8). Apocalipsis lo emplea para el testimonio profético (Ap 11:3), la estancia de la mujer en el desierto (Ap 12:6) y el atamiento milenario de Satanás y el reinado de los santos (Ap 20:2-7). El número transmite plenitud y soberanía divina sobre el tiempo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79002, 'spa', 'Tunica / prenda interior', 'Tunica / prenda interior. Vestidura que se llevaba directamente sobre la piel, distinta del manto exterior (ἱμάτιον). Jesus ensena a dar la tunica a quien demanda el manto (Mt 5:40; Lc 6:29), y los misioneros no deben llevar una de repuesto (Mt 10:10; Mc 6:9). Juan el Bautista exige compartir las tunicas con los necesitados (Lc 3:11). El sumo sacerdote rasga sus vestiduras en senal de indignacion (Mc 14:63), y las amigas de Tabita exhiben las tunicas que ella confecciono para las viudas (Hch 9:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79012, 'spa', 'Verde vegetal', 'Describe el color verde fresco de la vegetación viva. En Marcos 6:39 la multitud se sienta sobre la hierba verde antes de la alimentación de los cinco mil, y en Apocalipsis 9:4 las langostas demoníacas tienen prohibido destruir toda planta o árbol verde. Transmite el sentido de verdor vibrante y vital propio de la naturaleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79013, 'spa', 'Terrenal, de polvo', 'Relativo al polvo o la tierra, que caracteriza la naturaleza mortal y material de la humanidad formada del suelo (cf. Gn 2:7). Las cuatro apariciones se encuentran en 1 Corintios 15:47-49, donde Pablo contrasta al primer Adán terrenal con el Cristo celestial: el primer hombre es «del polvo» (v. 47), quienes comparten su naturaleza son «terrenales» (v. 48) y los creyentes han llevado la imagen del hombre terrenal (v. 49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79015, 'spa', 'Cerdo o puerco — animal ritualmente impuro según la ley mosaica', 'Cerdo o puerco — animal ritualmente impuro según la ley mosaica. Usado en el episodio de los endemoniados gadarenos (Mateo 8:30-32; Marcos 5:11-13; Lucas 8:32-33), la degradación del hijo pródigo (Lucas 15:15-16) y el proverbio sobre echar perlas a los cerdos (Mateo 7:6). El español ''cerdos'' traduce uniformemente un sentido único del animal doméstico impuro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79022, 'spa', 'Ser saciado o llenado — la experiencia intransitiva o pasiva de haber comido suf', 'Ser saciado o llenado — la experiencia intransitiva o pasiva de haber comido suficiente, quedar satisfecho con alimento. Usado tras las alimentaciones milagrosas donde miles comieron y ''fueron saciados'' (Mateo 14:20; Marcos 6:42), y escatológicamente en la Bienaventuranza ''Bienaventurados los que tienen hambre y sed de justicia, porque serán saciados'' (Mateo 5:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79023, 'spa', 'Saciar o alimentar a alguien — el sentido activo y causativo de proveer alimento', 'Saciar o alimentar a alguien — el sentido activo y causativo de proveer alimento suficiente para saciar. Los discípulos preguntan con asombro: ''¿De dónde podríamos conseguir suficiente pan para saciar a una multitud tan grande?'' (Mateo 15:33; Marcos 8:4). La construcción transitiva activa distingue este sentido de la experiencia pasiva de ser llenado; el énfasis recae en quien provee.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79033, 'spa', 'Hierba, vegetación verde — vegetación viva y verde que brota de la tierra', 'Hierba, vegetación verde — vegetación viva y verde que brota de la tierra. Usada para la hierba del campo que Dios adorna (Mateo 6:30; Lucas 12:28), la hierba verde donde las multitudes se recostaron (Mateo 14:19; Marcos 6:39), la hoja que brota antes de la espiga (Marcos 4:28) y la hierba que se marchita como metáfora de la fragilidad humana (Santiago 1:10-11; 1 Pedro 1:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79038, 'spa', 'Heno, hierba seca — vegetación cortada o marchita, usada metafóricamente como ma', 'Heno, hierba seca — vegetación cortada o marchita, usada metafóricamente como material de construcción perecedero. En 1 Corintios 3:12, Pablo advierte que edificar sobre el fundamento de Cristo con heno (junto con madera y paja) resultará en pérdida cuando sea probado por fuego. El español cambia a ''heno'' aquí, distinguiendo claramente este sentido seco y combustible de la ''hierba'' viva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79040, 'spa', 'Usar, hacer uso de', 'Usar, hacer uso de. Emplear algo con un proposito practico. Pablo recurre con frecuencia a este sentido al hablar de los derechos y libertades apostolicos: decidio no ''hacer uso'' de su derecho al sustento material (1 Co 9:12, 15, 18) y aconseja a los creyentes ''usar'' el mundo como si no dependieran de el (1 Co 7:31). Los marineros ''usan'' cables para reforzar un barco sacudido por la tormenta (Hch 27:17). El esclavo que puede obtener su libertad debe aprovecharla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79044, 'spa', 'Tratar, relacionarse con', 'Tratar, relacionarse con. Tratar o relacionarse con una persona de una manera determinada. En Hch 27:3 el centurion Julio ''trato'' a Pablo con bondad, permitiendole visitar a sus amigos en Sidon. Esta extension interpersonal no se centra en emplear una cosa, sino en la manera de conducir una relacion. El espanol ''tratar'' capta con precision este matiz, distinguiendolo del sentido instrumental de ''usar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79051, 'spa', 'Necesidad, carencia', 'Estado de requerir algo que falta, la cosa requerida o el servicio que se ha de prestar. Abarca la sentencia de Jesús de que los sanos no necesitan médico (Mt 9:12), el conocimiento divino de las necesidades humanas (Mt 6:8), la distribución de la primera comunidad (Hch 2:45) y la eclesiología paulina de mutua dependencia (1 Co 12:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79058, 'spa', 'Necesitar, requerir', 'Tener necesidad de algo, requerir — denota una carencia o necesidad genuina que reclama provisión o asistencia. Jesús lo usa para asegurar a los discípulos que su Padre celestial conoce sus necesidades materiales (Mt 6:32; Lc 12:30). También describe la necesidad nocturna de un vecino (Lc 11:8), la ayuda práctica que Febe requiere de la congregación romana (Ro 16:2) y la pregunta retórica de Pablo sobre necesitar cartas de recomendación (2 Co 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79059, 'spa', 'Dinero', 'Dinero como medio concreto de intercambio en transacciones específicas. En Hechos 4:37, Bernabé deposita χρήματα a los pies de los apóstoles tras vender un terreno; en Hechos 8:18-20, Simón ofrece dinero por poder espiritual y es duramente reprendido. Félix en Hechos 24:26 esperaba que Pablo le ofreciera un soborno, funcionando χρήματα como moneda de corrupción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79060, 'spa', 'Riquezas', 'Riquezas o bienes como condición general, frecuentemente en discursos morales o espirituales. Jesús advierte en Marcos 10:23-24 y Lucas 18:24 que quienes poseen χρήματα enfrentan particular dificultad para entrar en el reino de Dios. El español ''riquezas'' capta el sentido más amplio de bienes acumulados, en contraste con una suma concreta de dinero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79061, 'spa', 'Advertir divinamente', 'Recibir o transmitir una advertencia divina de parte de Dios. Se usa para los magos advertidos en sueños (Mt 2:12), José instruido a evitar Judea (Mt 2:22), Simeón con la promesa de ver al Mesías (Lc 2:26), Cornelio dirigido a enviar por Pedro (Hch 10:22), Noé advertido del diluvio (Heb 11:7) y Moisés instruido sobre el tabernáculo (Heb 8:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79063, 'spa', 'Ser llamado públicamente', 'Ser llamado, designado o conocido públicamente por un nombre o título. En Hechos 11:26, los discípulos fueron llamados (χρηματίσαι) cristianos por primera vez en Antioquía, una designación pública y oficial. En Romanos 7:3, una mujer ''será llamada'' (χρηματίσει) adúltera si vive con otro hombre mientras su esposo vive. El matiz subyacente es el de una denominación reconocida socialmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79074, 'spa', 'Bondadoso, benévolo', 'Bondadoso, benévolo, benigno — describe el carácter de Dios o la disposición que los creyentes deben cultivar. Dios es χρηστός con los ingratos y malvados (Lucas 6:35); su bondad (χρηστότης, el sustantivo relacionado) conduce al arrepentimiento (Romanos 2:4); y los creyentes deben ser χρηστοί unos con otros (Efesios 4:32). El español ''bondadoso'' resalta la buena voluntad activa, no la mera amabilidad pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79076, 'spa', 'Bueno, agradable', 'Bueno, agradable, sano — describe una calidad o carácter deseable e íntegro. El vino añejo es ''bueno'' (Lucas 5:39), las malas compañías corrompen las ''buenas'' costumbres (1 Corintios 15:33) y los creyentes han ''gustado que el Señor es bueno'' (1 Pedro 2:3, citando el Salmo 34:8). El rango semántico del vino a la ética muestra que χρηστός evalúa la calidad intrínseca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79079, 'spa', 'Fácil, cómodo', 'Fácil, cómodo, bien ajustado — describe un yugo o carga que no lastima. Se emplea únicamente en Mateo 11:30, donde Jesús dice ''mi yugo es χρηστός''. El sentido original de la palabra — ''útil, servible, bien hecho'' — se manifiesta aquí: un yugo fabricado por un carpintero hábil se ajusta perfectamente al animal. El español ''fácil'' capta la ligereza experimentada por quien lo lleva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79081, 'spa', 'Bondad, benignidad', 'Bondad, benignidad. Bondad, benignidad o benevolencia generosa, empleada predominantemente para describir el caracter de Dios y de modo secundario como virtud cristiana. Como atributo divino, conduce a los pecadores al arrepentimiento (Ro 2:4), se presenta en tension con la severidad divina (Ro 11:22) y se manifiesta escatologicamente en Cristo (Ef 2:7; Tit 3:4). Como virtud humana, figura entre los frutos del Espiritu (Ga 5:22) y en la autodescripcion apostolica de Pablo (2 Co 6:6; Col 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79083, 'spa', 'Unción espiritual', 'Las traducciones reflejan el sentido espiritual especializado del término: inglés ''anointing'', español ''unción'', francés conserva el griego ''χρῖσμα'', alemán ''Salbung''. Las tres apariciones se encuentran en 1 Juan 2, donde la unción representa la presencia interior del Espíritu Santo que enseña a los creyentes todas las cosas y los guarda del engaño de los anticristos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79084, 'spa', 'Seguidor de Cristo', 'El término se traduce de manera uniforme: inglés ''Christian'', español ''cristiano/cristianos'', francés ''chrétien'', alemán conserva el griego ''Χριστιανούς/Χριστιανόν''. Hechos 11:26 marca el primer uso del nombre en Antioquía, donde los creyentes gentiles formaron una comunidad distinta. Hechos 26:28 muestra que era reconocible incluso para funcionarios romanos como Agripa. 1 Pedro 4:16 anima a los creyentes a no avergonzarse de sufrir bajo este nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79085, 'spa', 'Cristo, Mesías, Ungido', 'Adjetivo griego sustantivado que significa ''ungido'', que sirve en el NT tanto como título mesiánico (''el Cristo'', Mt 2:4) cuanto como nombre propio vinculado a Jesús (''Jesucristo'', Ro 1:1). Traduce el hebreo מָשִׁיחַ y conlleva connotaciones de consagración real y sacerdotal. Las 540 ocurrencias apuntan a un único referente — Jesús de Nazaret — ya sea en fórmulas confesionales (Mt 16:16), en saludos epistolares o en la predicación kerygmática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79093, 'spa', 'Ungir, consagrar', 'Ungir como acto de consagración y comisión divina, siempre con Dios como agente implícito o explícito. Describe la unción del Espíritu sobre Jesús para su misión profética (Lc 4:18), la designación de Jesús como el Santo Siervo-Mesías (Hch 4:27; 10:38), la unción de los creyentes establecidos en Cristo (2 Co 1:21) y la unción de exaltación del Hijo con óleo de alegría (He 1:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79094, 'spa', 'Tardar, demorar', 'Tomar mucho tiempo, tardar o demorarse más de lo esperado, siempre en contextos de espera por la llegada de alguien. Se usa para la presunción del siervo malvado de que su señor tarda (Mt 24:48; Lc 12:45), el novio que se demora mientras las vírgenes duermen (Mt 25:5), la multitud que se extraña de la demora de Zacarías en el templo (Lc 1:21) y la promesa profética de que ‘el que viene no tardará’ (He 10:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79095, 'spa', 'Tiempo, período, duración', 'El tiempo concebido como extensión mensurable o período: un tramo que puede ser largo o corto, contado o estimado. Cubre lapsos narrativos («después de mucho tiempo», Mt 25:19), preguntas sobre duración (Mc 9:21) y periodización teológica («los tiempos de la ignorancia», Hch 17:30). Se distingue de καιρός por su énfasis en la cantidad más que en la cualidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79101, 'spa', 'De oro, áureo', 'De oro, áureo: describe objetos hechos de oro o recubiertos de oro, usado casi exclusivamente para mobiliario sagrado e imaginería visionaria celestial. He 9:4 lo emplea tres veces para el altar de oro, el arca de oro y la urna de oro con el maná del tabernáculo. Apocalipsis usa χρύσεος extensamente para objetos de adoración celestial: candeleros de oro (Ap 1:12, 20; 2:1), el cinto de oro del Hijo del Hombre (Ap 1:13), coronas de oro de los ancianos (Ap 4:4) y copas de oro (Ap 5:8; 15:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79102, 'spa', 'Oro (el metal precioso) — el metal precioso oro en cualquier forma', 'Oro (el metal precioso) — el metal precioso oro en cualquier forma: en bruto, refinado, acuñado o labrado en objetos. Pedro lo contrasta con la fe (1 Pedro 1:7), declara su carencia de él (Hechos 3:6) y aconseja contra la vana ostentación con él (1 Pedro 3:3). Apocalipsis lo usa para los adornos de Babilonia (Apocalipsis 17:4; 18:16). El español ''oro'' confirma un concepto semántico único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79108, 'spa', 'Oro', 'Oro. Oro como metal precioso, abarcando el oro material usado en ofrendas y objetos sagrados (Mt 2:11, la ofrenda de los magos; Ap 17:4; 18:12, 16, el adorno de Babilonia), el oro como moneda o riqueza (Mt 10:9, el encargo misionero; Hch 3:6; 20:33; 1 P 1:18) y el oro en los argumentos sobre juramentos en el templo (Mt 23:16-17, el oro del templo frente al templo que lo santifica). Santiago 5:3 advierte que el oro acumulado se corroera como testimonio contra quienes lo atesoran.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79113, 'spa', 'Cojo, lisiado — con discapacidad física en los pies o las piernas, incapaz de ca', 'Cojo, lisiado — con discapacidad física en los pies o las piernas, incapaz de caminar con normalidad; describe una condición crónica o congénita, no una lesión temporal. Aparece en los catálogos de sanaciones donde los cojos que caminan son señal de cumplimiento mesiánico (Mt 11:5; 15:30-31; 21:14; Lc 7:22), en la advertencia hiperbólica de Jesús sobre entrar en la vida mutilado (Mt 18:8; Mc 9:45) y en los relatos de sanación apostólica (Hch 3:2; 14:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79115, 'spa', 'Sentido predominante en los cuatro Evangelios y Hechos', 'Sentido predominante en los cuatro Evangelios y Hechos: un distrito geográfico o administrativo, provincia o país. Se usa para territorios con nombre como ''la tierra de los gadarenos'' (Marcos 5:1) y regiones más amplias como ''la región y sombra de muerte'' (Mateo 4:16). El español ''región'' y el francés ''contrée'' capturan este matiz de territorio delimitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79119, 'spa', 'Tierra agrícola abierta o campo, como en la exhortación de Jesús a alzar los ojo', 'Tierra agrícola abierta o campo, como en la exhortación de Jesús a alzar los ojos y mirar los campos listos para la siega (Juan 4:35) y los campos de los jornaleros cuyo salario clama (Santiago 5:4). Aquí el término lleva el sentido rural y cultivado, distinto del significado político-territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79121, 'spa', 'Tierra física o suelo visto como territorio o posesión material, como cuando la ', 'Tierra física o suelo visto como territorio o posesión material, como cuando la tierra de un hombre rico produjo abundantemente (Lucas 12:16) o los marineros percibieron que se acercaban a alguna tierra (Hechos 27:27). El énfasis recae sobre la tierra misma, no sobre límites jurisdiccionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79125, 'spa', 'Tener capacidad, contener', 'Tener capacidad, contener. Contencion fisica o capacidad espacial: tener lugar para algo o ser lo bastante grande para albergarlo. Las seis tinajas de piedra en Cana ''contenian'' cada una dos o tres medidas (Jn 2:6); la casa ya no podia ''contener'' a la multitud (Mc 2:2); el mundo mismo no podria ''contener'' todos los libros (Jn 21:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79126, 'spa', 'Aceptar, recibir, dar lugar', 'Aceptar, recibir, dar lugar. Recepcion figurada: aceptar o acoger una ensenanza, verdad o persona en la mente o el corazon. Jesus dice que ''no todos pueden recibir esta palabra'' acerca del celibato (Mt 19:11-12), y Pablo suplica ''hacednos lugar'' (2 Co 7:2). El desplazamiento del espacio fisico a la disposicion interior refleja el arco semantico del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79131, 'spa', 'Ir, moverse, avanzar', 'Ir, moverse, avanzar. Movimiento o progresion de un lugar a otro, conservando el sentido clasico mas antiguo de ''avanzar''. Jesus pregunta adonde ''va'' la comida despues de comer (Mt 15:17), y Pedro escribe que el Senor es paciente, queriendo que todos ''lleguen'' al arrepentimiento (2 P 3:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79135, 'spa', 'Separar, dividir (transitivo) — desunir activamente o poner aparte', 'Separar, dividir (transitivo) — desunir activamente o poner aparte. Jesús advierte «lo que Dios unió, que no lo separe el hombre» (Mt 19:6; Mc 10:9), y Pablo pregunta retóricamente quién podrá «separarnos del amor de Cristo» (Ro 8:35, 39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79136, 'spa', 'Partir, irse (intransitivo) — retirarse, marcharse, especialmente en el contexto', 'Partir, irse (intransitivo) — retirarse, marcharse, especialmente en el contexto de separación conyugal. Pablo instruye a la esposa a no «separarse de» su marido (1 Co 7:10-11, 15), y Hechos registra partidas: Saulo dejando Damasco (Hch 1:4), Pablo separándose de Atenas (Hch 18:1) y Aquila dejando Italia (Hch 18:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79144, 'spa', 'Apartado, designado — estado resultante o consecratorio', 'Apartado, designado — estado resultante o consecratorio: estar apartado, destinado a un oficio. Hebreos 7:26 describe a Jesús como un sumo sacerdote «apartado de los pecadores», no meramente distante sino consagrado a una condición santa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79147, 'spa', 'Campo, terreno, propiedad — un campo, terreno o finca considerada como bien que ', 'Campo, terreno, propiedad — un campo, terreno o finca considerada como bien que puede comprarse, venderse o poseerse. Predomina en los relatos de Hechos sobre la iglesia primitiva: Judas adquiere un campo con el dinero de sangre (Hch 1:18–19), Ananías y Safira venden su terreno y retienen parte del precio (Hch 5:3, 8), y los creyentes que poseen propiedades las venden para uso comunitario (Hch 4:34). También se usa para la parcela de Jacob cerca de Sicar (Jn 4:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79148, 'spa', 'Lugar, sitio, localidad — un lugar, sitio o localidad con nombre, que enfatiza e', 'Lugar, sitio, localidad — un lugar, sitio o localidad con nombre, que enfatiza el entorno geográfico más que la posesión. Se emplea para Getsemaní (Mt 26:36; Mr 14:32), donde el enfoque está en llegar a un sitio determinado para orar, no en quién posee el terreno. El español ''lugar'' capta este sentido puramente espacial, en contraste con el vocabulario ligado a la propiedad que se usa en los pasajes de Hechos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79153, 'spa', 'Preposición impropia con genitivo que indica separación, ausencia o exclusión', 'Preposición impropia con genitivo que indica separación, ausencia o exclusión: ''sin'' o ''aparte de''. Tiene un peso teológico decisivo en Pablo y Hebreos: ''aparte de la ley'' (Romanos 3:21; 7:8-9), ''sin fe'' (Hebreos 11:6), ''sin derramamiento de sangre'' (Hebreos 9:22). Juan 1:3 y 15:5 la emplean para expresar dependencia absoluta de Cristo. También funciona en fórmulas de exclusión numérica: ''sin contar mujeres y niños'' (Mateo 14:21; 15:38), donde significa ''además de''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79159, 'spa', 'Cantar alabanzas', 'Cantar alabanzas o hacer música a Dios, originalmente con la connotación de pulsar cuerdas, pero en el uso neotestamentario referido principalmente a la adoración vocal y el canto de salmos. Pablo cita el Salmo 18:49 declarando ''cantaré alabanzas entre las naciones'' (Ro 15:9), se compromete a cantar con el espíritu y con el entendimiento (1 Co 14:15), y exhorta a los creyentes a salmodiar en sus corazones al Señor (Ef 5:19). Santiago lo prescribe como expresión de alegría (Stg 5:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79161, 'spa', 'Salmo o canto sagrado', 'Salmo o canto sagrado entonado con acompañamiento de cuerdas, que abarca tanto las referencias al libro veterotestamentario de los Salmos como Escritura autoritativa (Lucas 20:42: ''David mismo dice en el libro de los Salmos''; Hechos 13:33: ''como está escrito en el salmo segundo'') como la práctica de cantar salmos en la adoración cristiana primitiva (1 Corintios 14:26: ''cada uno tiene un salmo''). La raíz etimológica en el pulsado de cuerdas conecta el término con la interpretación musical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79167, 'spa', 'Falso y mentiroso', 'La evidencia interlingüística refleja una fuerte condena moral: «falsos», «mentirosos» en español, «menteur» en francés, «lügnerisch» en alemán. Hechos 6:13 describe testigos que deliberadamente declararon en falso contra Esteban. Apocalipsis 2:2 alaba el discernimiento que desenmascaró a falsos apóstoles. Apocalipsis 21:8 coloca a los mentirosos junto a homicidas y hechiceros entre los condenados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79170, 'spa', 'Mentir, hablar falsamente — decir mentiras o hablar con falsedad de manera delib', 'Mentir, hablar falsamente — decir mentiras o hablar con falsedad de manera deliberada. Abarca juramentos de veracidad (''no miento'', Ro 9:1; Gá 1:20), el mandato contra la mentira (Col 3:9), el engaño de Ananías (Hch 5:3), la imposibilidad divina de mentir (He 6:18) y la acusación falsa (Mt 5:11). Un único sentido de falsedad intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79178, 'spa', 'Dar falso testimonio', 'Dar testimonio falso, declarar de manera mendaz, específicamente en contextos legales o judiciales regidos por el noveno mandamiento. Jesús lo incluye entre los mandamientos que deben guardarse (Mt 19:18; Mr 10:19; Lc 18:20), haciendo eco de Éxodo 20:16 y Deuteronomio 5:20. Marcos lo aplica a los testigos en el juicio de Jesús cuyo testimonio no concordaba (Mr 14:56-57). Las cinco apariciones mantienen el registro forense y covenantal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79180, 'spa', 'Falso profeta — quien reclama fraudulentamente tener revelación divina, extravia', 'Falso profeta — quien reclama fraudulentamente tener revelación divina, extraviando al pueblo de Dios mediante enseñanza engañosa o señales falsificadas. Jesús advierte de su actitud de lobos con piel de oveja (Mt 7:15), predice su proliferación en los últimos tiempos con señales engañosas (Mt 24:11, 24; Mr 13:22) y señala que los falsos profetas eran aclamados popularmente (Lc 6:26). Juan insta a probar los espíritus (1 Jn 4:1). En Apocalipsis, el falso profeta personifica la propaganda de la bestia (Ap 16:13; 19:20; 20:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79183, 'spa', 'Mentira, falsedad — una mentira, falsedad o engaño deliberado, contradicción int', 'Mentira, falsedad — una mentira, falsedad o engaño deliberado, contradicción intencionada de la realidad, teológicamente opuesta al Dios que es verdad. Abarca el origen satánico (Jn 8:44, el diablo como padre de la mentira), el intercambio idolátrico (Ro 1:25, cambiar la verdad de Dios por la mentira), la exhortación ética (Ef 4:25, desechar la mentira), el engaño escatológico (2 Ts 2:9-11, señales mentirosas y el poder engañoso para creer la mentira) y la exclusión final (Ap 21:27; 22:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79188, 'spa', 'Mentiroso, el que habla falsedad — aquel que característicamente profiere falsed', 'Mentiroso, el que habla falsedad — aquel que característicamente profiere falsedad. Aplicado al diablo como mentiroso arquetípico (Jn 8:44), a los seres humanos universalmente (Ro 3:4, ''todo hombre mentiroso'', citando Sal 116:11), y a todo aquel cuya vida contradice su confesión de fe (Jn 8:55; 1 Jn 1:10; 2:4, 22; 4:20; 5:10). El uso juanino es especialmente incisivo: negar que Jesús es el Cristo, decir que se ama a Dios mientras se odia al hermano, todo ello constituye mentira.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79191, 'spa', 'Palpar o tantear', 'Tocar, palpar o buscar a tientas, ya sea manejando literalmente un cuerpo físico o buscando figuradamente mediante el tacto. En Lucas 24:39 el Cristo resucitado dice «palpadme y ved» para demostrar su resurrección corporal, y 1 Juan 1:1 recuerda las manos que «palparon» al Verbo encarnado. Hechos 17:27 extiende la imagen metafóricamente: Dios dispuso el mundo para que los hombres le buscasen a tientas y le hallasen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79193, 'spa', 'Piedrecita o voto', 'Las traducciones reflejan tanto lo literal como lo metafórico: «piedrecita» y «voto» en español, «caillou» en francés, «Stein» en alemán. Hechos 26:10 usa el término para el voto de Pablo contra los creyentes, una piedrecita arrojada en juicio. La «piedra blanca» de Apocalipsis 2:17 resulta más enigmática: podría representar un símbolo de victoria, absolución o admisión al banquete mesiánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79197, 'spa', 'alma, ser interior', 'El yo inmaterial interior: sede de sentimientos, deseos, vida moral e identidad espiritual. Este sentido predominante (100 ocurrencias) aparece en la enseñanza de Jesús sobre amar a Dios con toda el alma (Mt 22:37), en el cántico de María (Lc 1:46) y en la solicitud pastoral de Pablo (1 Ts 2:8). El español ''alma'', el francés âme y el alemán Seele captan esta dimensión íntima y personal que trasciende lo meramente físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79201, 'spa', 'vida, existencia física', 'Vida física y mortal que puede arriesgarse, perderse o preservarse. En Hch 27:10, 22 Pablo habla de las ψυχαί (vidas) de los que iban en el barco azotado por la tormenta, y Ap 8:9 describe a las criaturas marinas perdiendo su ψυχή. Las formas plurales en diversas lenguas marcan el paso de la interioridad del ser al conteo de existencias mortales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79207, 'spa', 'Natural, anímico', 'Relativo a la vida natural gobernada por la ψυχή, no por el πνευμα divino. Tiene fuerza peyorativa o limitante en el NT: la persona ψυχικός carece de percepción espiritual (1 Cor 2:14), el cuerpo ψυχικόν pertenece a la era de mortalidad (1 Cor 15:44-46), y la sabiduría ψυχική se alinea con lo terrenal y demoníaco (Jas 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79211, 'spa', 'Frío o frialdad', 'La palabra se traduce de manera uniforme: «frío» en español, «froid» en francés, «Kälte» en alemán, todas indicando temperatura baja o condiciones heladas. Juan 18:18 retrata el aire frío nocturno durante el juicio de Jesús. Hechos 28:2 describe la lluvia gélida en Malta que movió a los nativos a la compasión. 2 Corintios 11:27 sitúa el frío junto a la desnudez, el hambre y la sed entre las penurias apostólicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79212, 'spa', 'Frío o gélido', 'Frío en temperatura o, por extensión, en disposición espiritual. Literalmente, Mateo 10:42 habla de dar un vaso de agua fría (ψυχρός) como acto de caridad. Figuradamente, Apocalipsis 3:15-16 emplea la tríada frío-caliente-tibio para diagnosticar la apatía espiritual de Laodicea: ser frío al menos sería una postura decidida, mientras que la tibieza provoca el rechazo del Señor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79215, 'spa', 'Bocado de pan', 'Un pequeño trozo de pan o alimento, específicamente uno mojado y compartido en una comida comunitaria. Las cuatro apariciones se concentran en Juan 13:26-30, donde Jesús identifica a su traidor mojando el bocado (ψωμίον) y entregándoselo a Judas. El acto de compartir el pan subraya la comunión de mesa que la traición viola de manera tan devastadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79217, 'spa', 'Título divino final', 'Última letra del alfabeto griego empleada como título divino que expresa finalidad, consumación y soberanía absoluta. Aparece exclusivamente en Apocalipsis (1:8, 1:11, 21:6, 22:13), siempre en el par «Alfa y Omega», un merismo que declara la presencia de Dios tanto en el origen como en la culminación de todas las cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79218, 'spa', '¡Oh!', '¡Oh!: exclamación vocativa usada para dirigirse directamente a personas, típicamente con emoción intensa — ya sea pesar, asombro, reprensión o admiración. Jesús la usa para lamentar la incredulidad (''¡Oh generación incrédula!'', Mc 9:19) y para elogiar una confianza excepcional (''¡Oh mujer, grande es tu fe!'', Mt 15:28). Pablo la despliega en interpelación retórica incisiva (''¡Oh gálatas insensatos!'', Gá 3:1). La partícula es prácticamente intraducible y se mantiene estable como ''¡Oh'' en español.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79221, 'spa', 'Nombre propio: Obed', 'El nombre se mantiene consistente en las traducciones: «Obed» en español e inglés, «Ἰωβήδ» en el texto griego. Mateo 1:5 sitúa a Obed en la genealogía inmediatamente después de Booz y Rut, destacando la inclusión de una mujer gentil en la línea mesiánica. Lucas 3:32 confirma su posición en el linaje que asciende desde Jesús hasta David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79222, 'spa', 'Aquí, en este lugar', 'Adverbio demostrativo que indica la ubicación del hablante o el lugar en cuestión: «aquí» o «en este lugar». Puntúa declaraciones cristológicas de gran fuerza: «uno mayor que el templo está aquí» (Mt 12:6), «mayor que Salomón está aquí» (Mt 12:42) y «no está aquí; ha resucitado» (Mt 28:6). A veces implica movimiento: «traédmelos aquí» (Mt 14:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79226, 'spa', 'Canción, oda, himno', 'Canción, himno u oda de adoración y alabanza que siempre aparece en contextos de canto gozoso o exaltado ante Dios. En las epístolas paulinas, ᾠδή figura junto a salmos e himnos como forma de expresión comunitaria llena del Espíritu (Efesios 5:19; Colosenses 3:16). En Apocalipsis, designa el trascendente ''cántico nuevo'' de los redimidos (Apocalipsis 5:9; 14:3). El español ''cántico'' refleja la cualidad lírica y melódica del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79228, 'spa', 'Dolores de parto', 'Los agudos dolores del alumbramiento, usados literalmente del parto y figuradamente del sufrimiento intenso que precede la liberación o una nueva era. En Mateo 24:8 y Marcos 13:8, Jesús llama a las tribulaciones apocalípticas el «principio de dolores de parto» (ἀρχὴ ὠδίνων), sugiriendo una intensificación inevitable antes de que llegue la nueva creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79229, 'spa', 'Dolores de parto', 'Las traducciones enfatizan el proceso del alumbramiento: «estar de parto», «sufrir dolores de parto» en español, «enfantant» en francés, «gebärend» en alemán. Gálatas 4:19 emplea la imagen para la angustia espiritual de Pablo ante la inmadurez de los gálatas. Gálatas 4:27, citando a Isaías, contrasta a la estéril con la que tiene marido. Apocalipsis 12:2 retrata el parto cósmico de la mujer celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79233, 'spa', 'hora, tiempo, momento', 'Un período de tiempo que va desde una hora concreta del reloj hasta un momento decisivo y divinamente señalado. Comprende la indicación horaria literal (''como a la hora sexta,'' Mt 27:45), momentos instantáneos de sanación (''desde aquella hora,'' Mt 8:13; 9:22), la ''hora'' destinada de la pasión y glorificación de Jesús (Jn 2:4; 12:23), y puntos de inflexión escatológicos (Ap 3:10). El término griego tiende un puente entre χρόνος (tiempo medido) y καιρός (momento oportuno).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79236, 'spa', 'Hermoso, bello', 'Hermoso, bello o atractivo en apariencia, a menudo con un matiz de oportunidad o conveniencia estacional. En Mateo 23:27, Jesús lo usa irónicamente de sepulcros blanqueados que parecen ὡραῖοι por fuera pero encubren muerte. La «Puerta Hermosa» (Hch 3:2, 10) recibía su nombre por su esplendor ornamental. En Romanos 10:15 la belleza se aplica a los pies de quienes proclaman el evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79238, 'spa', 'comparativo: como', 'Sentido comparativo: ''como,'' ''al igual que'' — el significado dominante con cerca del 78% de las ocurrencias, establece una semejanza o un paralelo de manera. ''Hágase tu voluntad en la tierra como en el cielo'' (Mt 6:10) y ''sed perfectos como vuestro Padre es perfecto'' (Mt 5:48) son ejemplos paradigmáticos. El español como, el francés comme y el alemán wie convergen aquí en su valor comparativo por defecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79239, 'spa', 'temporal: cuando', 'Sentido temporal: ''cuando,'' ''mientras'' — introduce una cláusula temporal, especialmente en la narrativa lucana. ''Cuando se cumplieron los días de su servicio'' (Lc 1:23) y ''cuando Elisabet oyó el saludo de María'' (Lc 1:41). El coreano ttae (''cuando'') y el español cuando lo distinguen nítidamente del comparativo como, confirmando un auténtico sentido temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79240, 'spa', 'aproximativo: como', 'Sentido aproximativo: ''como,'' ''aproximadamente'' — se emplea con cifras o cantidades para expresar una estimación. ''Como dos mil'' cerdos (Mc 5:13), ''como cuatro mil'' hombres (Mc 8:9), ''como de doce años'' (Lc 8:42). El español como conserva la ambigüedad, pero el coreano yak y el hindi lagbhag señalan la aproximación de forma inequívoca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79242, 'spa', 'exclamativo: cuán, cómo', 'Sentido exclamativo: ''¡cómo!,'' ''¡cuán!'' — introduce una exclamación de grado o manera. ''Cómo observaron la tumba las mujeres que habían venido con él desde Galilea'' (Lc 23:55) y ''cómo había sido sanada al instante'' (Lc 8:47). El español cuán/cómo y el alemán wie cumplen esta doble función como partículas exclamativas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79244, 'spa', 'hipotético: como si', 'Comparación hipotética: ''como si'' — introduce un escenario imaginado o contrafáctico. Pedro rechaza el mérito ''como si por nuestro propio poder le hubiéramos hecho andar'' (Hch 3:12), y los conjurados fingen intención ''como si quisieran investigar más de cerca'' (Hch 23:15). El francés comme si y el coreano machi ayudan a distinguirlo de la comparación factual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79248, 'spa', 'final: para', 'Sentido final: ''para,'' ''a fin de'' — expresa un resultado buscado, normalmente con infinitivo. Jesús envió mensajeros ''para prepararle alojamiento'' (Lc 9:52) y Pablo tiene en nada su propia vida ''para acabar mi carrera'' (Hch 20:24). El español para y el francés pour confirman la lectura de finalidad, distinta de la comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79252, 'spa', 'temporal: desde que', 'Punto de partida temporal: ''desde que,'' ''desde cuando'' — marca un origen en el tiempo. Solo una ocurrencia: ''¿Desde cuándo le sucede esto?'' (Mc 9:21). El español desde que y el francés depuis que distinguen este sentido temporal retrospectivo del ''cuando'' simultáneo del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79255, 'spa', 'Hosanna', 'Clamor litúrgico hebreo que significaba «¡Salva ahora!» (Psalm 118:25), convertido para el Segundo Templo en exclamación de alabanza y aclamación mesiánica. En la Entrada Triunfal (Matt 21:9; Mark 11:9-10) las multitudes la usan para aclamar a Jesús como Mesías davídico, y en Matt 21:15 los niños la repiten en el templo, provocando a los principales sacerdotes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79256, 'spa', 'Igualmente, del mismo modo', 'Igualmente, del mismo modo: adverbio de modo que indica que algo se hace de la misma manera o con el mismo efecto que lo anterior. Estructura el paralelismo narrativo en las parábolas — cada grupo de obreros o cada hijo responde ''igualmente'' (Mt 20:5; 21:30, 36). En las epístolas conecta expectativas de conducta: los diáconos deben ''igualmente'' ser dignos (1 Ti 3:8), las esposas ''asimismo'' sumisas (1 P 3:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79260, 'spa', 'Se usa con numerales o expresiones temporales para indicar aproximación', 'Se usa con numerales o expresiones temporales para indicar aproximación: ''como, aproximadamente, alrededor de''. Lucas emplea este uso con especial frecuencia: ''como cinco mil'' (Lucas 9:14), ''como de treinta años'' (Lucas 3:23), ''como ocho días después'' (Lucas 9:28). El francés ''environ'' y el alemán ''etwa'' son equivalentes casi exactos, mientras que el español ''como'' sirve tanto para este sentido como para el comparativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79261, 'spa', 'Introduce comparaciones y símiles', 'Introduce comparaciones y símiles: ''como, como si, a manera de''. El Espíritu desciende sobre Jesús ''como paloma'' (Mateo 3:16), las multitudes son ''como ovejas sin pastor'' (Mateo 9:36) y en Getsemaní el sudor de Jesús cae ''como gotas de sangre'' (Lucas 22:44). Los discípulos desestimaron el relato de las mujeres ''como palabras vanas'' (Lucas 24:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79263, 'spa', 'Partícula comparativa que significa ''así como'' o ''tal como'', introduciendo paral', 'Partícula comparativa que significa ''así como'' o ''tal como'', introduciendo paralelismos y semejanzas. Refuerza el simple ὡς con la partícula enfática περ, produciendo una comparación más exacta y enfática. Jesús la emplea para analogías parabólicas (Mateo 12:40; 13:40) y comparaciones éticas (Mateo 6:2, 7). Pablo la utiliza para paralelos tipológicos entre Adán y Cristo (Romanos 5:19; 1 Corintios 15:22). El español ''así como'' refleja fielmente esta función comparativa intensificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79265, 'spa', 'de modo que', 'Conjunción consecutiva que expresa resultado, consecuencia o conclusión lógica: ''de modo que,'' ''así que,'' ''por lo tanto.'' Se construye con infinitivo para resultado natural (Mt 8:24, la barca se anegaba ''de modo que'' quedaba cubierta) o como conector oracional para conclusiones (1 Co 3:21, ''así que nadie se jacte'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79270, 'spa', 'Oreja externa', 'La oreja externa, el pabellón auricular — forma diminutiva de οὖς que en el uso neotestamentario no conserva matiz diminutivo y simplemente designa la oreja física. Las cinco apariciones se refieren al incidente en Getsemaní donde Pedro corta la oreja del siervo del sumo sacerdote, Malco (Mt 26:51; Mr 14:47; Jn 18:10, 26), y Lucas registra la restauración milagrosa por parte de Jesús (Lc 22:51).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79272, 'spa', 'Ser beneficiado, obtener provecho — recibir beneficio o ventaja (pasivo/medio)', 'Ser beneficiado, obtener provecho — recibir beneficio o ventaja (pasivo/medio). La mujer que gastó todo en médicos ''no fue beneficiada'' (Mc 5:26). Jesús desafía: ''¿De qué le aprovecha al hombre ganar el mundo entero?'' (Mt 16:26; Lc 9:25). Los votos de Corbán (Mt 15:5; Mc 7:11) irónicamente niegan el beneficio a los padres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79276, 'spa', 'Ser de utilidad, servir — ser útil o valer (intransitivo/absoluto)', 'Ser de utilidad, servir — ser útil o valer (intransitivo/absoluto). Pilato vio que ''no lograba nada'' (Mt 27:24). ''La carne para nada aprovecha'' (Jn 6:63). El retórico ''¿de qué os aprovecháis?'' de Pablo (Ro 2:25) y la exasperación de los fariseos ''no estáis logrando nada'' (Jn 12:19) despliegan este sentido impersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79281, 'spa', 'Beneficiar a alguien, ayudar — beneficiar, ser de provecho para otro (transitivo', 'Beneficiar a alguien, ayudar — beneficiar, ser de provecho para otro (transitivo activo). Pablo pregunta de qué les aprovecharía a los corintios si viniera hablando solo en lenguas (1 Co 14:6). Advierte a los gálatas que Cristo ''de nada os aprovechará'' si confían en la circuncisión (Gá 5:2). Hebreos 4:2 dice que la palabra ''no les aprovechó'' a quienes carecían de fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79286, 'spa', 'Provechoso, útil', 'Útil, ventajoso o que produce un beneficio genuino para un propósito o persona determinados. En las Epístolas Pastorales, Pablo emplea este término para sopesar bienes en competencia: el ejercicio físico es ὠφέλιμος «para poco» mientras que la piedad lo es «para todo» (1 Ti 4:8), creando una escala memorable de valor. El mismo tono práctico aparece en 2 Ti 3:16, donde la utilidad de la Escritura se desglosa en cuatro dimensiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79287, 'spa', 'padre directo (variante)', 'Variante del padre inmediato que aparece en contextos donde la relacion paterno-filial directa se enfatiza mediante construcciones posesivas o vocativas: ''mi padre,'' ''padre mio.'' Funcionalmente sinonimo del sentido 1, esta separacion refleja patrones de traduccion multilingue donde las formas posesivas generan agrupaciones de glosas distintas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79293, 'spa', 'antepasado, patriarca', 'Antepasados o patriarcas, usado abrumadoramente en plural (אָבוֹת) para designar generaciones anteriores del linaje de Israel — los que salieron de Egipto, recibieron el pacto o pecaron en el desierto. Con 146 apariciones, este sentido ancla frases como ''el Dios de vuestros padres'' (Ex 3:13) y ''la tierra jurada a vuestros padres.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79296, 'spa', 'jefe de casa paterna', 'El jefe patriarcal del clan en la expresion institucional בֵּית אָבוֹת (''casas paternas''), la unidad organizativa basica de la estructura tribal israelita para el censo, la leva militar y el servicio sacerdotal. Concentrado en Numeros y Cronicas (35 apariciones), este sentido administrativo aparece en pasajes como 1 Cr 7:40 (''jefes de casas paternas, hombres escogidos, valientes guerreros'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79375, 'spa', 'Padre, ancestro (arameo)', 'Padre o ancestro en las porciones arameas de las Escrituras. Se usa con sufijos pronominales para denotar paternidad directa (Dn 5:2, ''tu padre Nabucodonosor''), linaje ancestral (Esd 4:15, ''el libro de las memorias de tus padres'') o relación teológica (Dn 2:23, ''Dios de mis padres''). El español lo traduce consistentemente como ''padre/padres'', reflejando el sentido fundamental de parentesco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79382, 'spa', 'Fruto vegetal', 'Las traducciones coinciden en «fruto» o «su fruto». En Daniel 4:12 se describe el fruto del árbol como abundante, alimento para toda criatura. El versículo 14 ordena esparcir el fruto como parte de la destrucción del árbol. El versículo 21 repite la imagen de fruto copioso. El sueño emplea imaginería agrícola para representar la provisión y el juicio sobre el reino de Nabucodonosor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79384, 'spa', 'perecer, ser destruido', 'Perecer, ser destruido, dejar de existir (Qal intransitivo): el significado nuclear con 105 ocurrencias. Abarca todo el espectro de la destrucción terminal: naciones que perecen bajo el juicio divino (Dt 4:26; 8:19-20), los impíos que se consumen (Sal 1:6; 37:20), la esperanza que muere (Job 8:13) y la memoria que se borra (Sal 9:6). El árabe هَلَكَ y فَنِيَ marcan de modo consistente esta misma dimensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79387, 'spa', 'hacer perecer (Hifil)', 'Hacer perecer, llevar a la destrucción (Hifil causativo): 27 ocurrencias en que un agente (normalmente Dios) causa que el objeto perezca. Se distingue del Piel al enfatizar la cadena causal: ''Jehová tu Dios los hará perecer'' (Dt 7:24), ''destruiré de en medio de su pueblo'' (Lv 23:30). El Hifil focaliza la autoridad detrás de la destrucción más que la intensidad del acto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79392, 'spa', 'destruir, aniquilar (Piel)', 'Destruir, exterminar, aniquilar (Piel intensivo): 38 ocurrencias de destrucción activa ejercida por un agente. Se ordena a Israel destruir los lugares altos idolátricos (Dt 12:2), y Dios amenaza con destruir a los pueblos desobedientes (Nm 33:52). La fuerza intensiva del Piel no significa solo matar, sino erradicar —borrar todo vestigio. El árabe أَهْلَكَ (forma IV causativa) y أَبَادَ reflejan esta misma intensidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79402, 'spa', 'perderse, extraviarse', 'Perderse, extraviarse, andar errante (Qal intransitivo): 13 ocurrencias en que el significado pasa de la destrucción al desplazamiento. Las burras del padre de Saúl ''se habían perdido'' (1 S 9:3, 20); la ley ordena devolver el animal perdido del prójimo (Dt 22:3); el arameo errante de Dt 26:5 es un אֹבֵד —perdido, vulnerable, a punto de perecer. El árabe ضَاعَ distingue este sentido del de destrucción catastrófica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79429, 'spa', 'desperdiciar, malgastar (Piel)', 'Desperdiciar, malgastar, disipar (subsentido del Piel): 2 ocurrencias en que el objeto no se destruye violentamente sino que se disipa por necedad o por el paso del tiempo. En Pr 29:3, el que frecuenta prostitutas ''desperdicia'' su hacienda; en Ec 3:6, hay ''tiempo de perder.'' El árabe يُضِيعُ marca esto como pérdida por descuido, no destrucción deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79500, 'spa', 'Destruir (Hifil causativo)', 'Destruir, hacer perecer (Hifil causativo). El sentido transitivo predomina en las narrativas cortesanas de Daniel: el rey ordena «destruir» a los sabios en Dn 2:12, y Daniel busca misericordia urgente «para que no los destruyan» en 2:18. En Dn 7:26, el tribunal divino actúa para destruir el dominio, trasladando la agencia del poder humano al celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79502, 'spa', 'Perecer, ser destruido', 'Perecer, ser destruido (Qal intransitivo / Hofal pasivo). El sujeto sufre la destrucción en vez de infligirla. Jeremías 10:11, el único versículo arameo de ese libro, declara que los dioses que no crearon cielo ni tierra «perecerán» — una maldición profética en forma yusiva. En Dn 7:11, la bestia «fue destruida» (Hofal pasivo), recibiendo el juicio decretado por el Anciano de Días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79507, 'spa', 'Objeto perdido', 'Un objeto o propiedad perdida que alguien ha extraviado o que se ha descarriado. En Éx 22:9 aparece en una lista de casos de propiedad en disputa. Lv 6:3-4 aborda la obligación moral cuando alguien encuentra una אֲבֵדָה y miente al respecto: se requiere restitución más una quinta parte. Dt 22:3 amplía el deber de devolver cualquier objeto perdido del prójimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79508, 'spa', 'Abadón / lugar de destrucción', 'Abadón — el lugar o personificación de la destrucción en el reino de los muertos. Se emplea en la poesía hebrea como sinónimo de Seol, la tumba y la muerte (Job 26:6, paralelo a Seol; Job 28:22, paralelo a Muerte; Pr 15:11; Sal 88:11). En Job 31:12 denota una ruina consumidora como fuerza destructiva. El nombre deriva de אָבַד (''perecer''), y el español «Abadón» preserva el sentido de aniquilación total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79516, 'spa', 'querer, estar dispuesto', 'Estar dispuesto, querer o tener la inclinación de hacer algo, expresando disposición volitiva o prontitud. Aunque el significado subyacente es positivo (''estar dispuesto''), aparece casi siempre negado, formando un fuerte modismo de rechazo. El español ''quiso'' (del verbo ''querer'') capta el núcleo volitivo. Clave: Dt 1:26 (Israel no quiso subir), Éx 10:27 (Faraón no quiso dejarlos ir).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79527, 'spa', 'consentir, acceder', 'Consentir o acceder a una propuesta concreta — un acto deliberado de aceptación, no una disposición general. Se distingue del sentido 1 por la presencia de una oferta específica. En Pr 1:10 (''si los pecadores te seducen, no consientas''), el verbo marca el momento decisivo de ceder. En 1 R 20:8 los ancianos aconsejan no acceder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79539, 'spa', 'Pesebre, comedero', 'Las traducciones coinciden en «pesebre» o «comedero»: español «pesebre», francés «crèche», alemán «Krippe». Job 39:9 contrasta al buey salvaje con los animales domésticos que duermen junto al comedero. Proverbios 14:4 reconoce que los bueyes requieren cuidado pero traen gran provecho. La acusación de Isaías 1:3 es conmovedora: hasta los asnos conocen el pesebre de su amo, pero Israel no reconoce a su Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79543, 'spa', 'Nombre propio', 'El nombre se transliteró de forma consistente como Abiel. En 1 Samuel 9:1 se identifica a Abiel en la genealogía de Saúl como hijo de Zeror. 1 Samuel 14:51 confirma que tanto Saúl como Abner eran nietos de Abiel. 1 Crónicas 11:32 enumera a un Abiel entre los valientes de David, aunque su identificación con el abuelo de Saúl es incierta. El nombre teofórico expresa confianza filial en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79545, 'spa', 'Aviv, mes de maduración', 'El mes de Aviv, primer mes del calendario hebreo correspondiente a marzo-abril, cuando las espigas de cebada maduran. Es el mes del Éxodo y la Pascua. Éxodo 13:4 registra: ''Vosotros salís hoy, en el mes de Aviv.'' El artículo ha-Aviv lo marca como nombre propio del mes, mientras ''espiga'' alude a su origen agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79547, 'spa', 'Espigas tiernas de grano', 'Espigas frescas y tiernas de cebada que se han formado en el tallo pero aún no han madurado plenamente. En Éxodo 9:31, la cebada fue destruida por la séptima plaga porque estaba ''en espiga'' (aviv). Levítico 2:14 prescribe una ofrenda de primicias: espigas frescas tostadas al fuego (aviv qalui ba-esh).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79549, 'spa', 'Abigail (nombre propio)', 'Abigail (nombre propio). Nombre personal que aparece en múltiples variantes ortográficas (אֲבִיגַיִל, אֲבִיגַל, אֲבִיגָל). Designa principalmente a la mujer ingeniosa de Carmel que impidió que David derramara sangre por ira (1 Sam 25:14-35) y que luego le dio un hijo, Quileab (2 Sam 3:3). También designa a la hermana de David, madre de Amasa (1 Cr 2:16-17; 2 Sam 17:25). Las traducciones en distintos idiomas la transliteran de manera consistente.');